package com.trush.game.gfx;

import com.badlogic.gdx.graphics.Color;
import com.badlogic.gdx.graphics.Texture;
import com.badlogic.gdx.graphics.g2d.SpriteBatch;
import com.badlogic.gdx.math.MathUtils;
import com.badlogic.gdx.utils.Disposable;

/** First two authored enemies. Six poses and three palettes, generated by gen_sprites.py. */
public final class KinArt implements Disposable {
    private static final float PPU = 64f;
    private final Texture bullet = load("bullet_kin");
    private final Texture shell = load("shotgun_kin");
    private final Texture weapons = load("kin_weapons");

    private static Texture load(String name) {
        Texture texture = new Texture("assets/sprites/" + name + ".png");
        texture.setFilter(Texture.TextureFilter.Nearest, Texture.TextureFilter.Nearest);
        return texture;
    }

    public void body(SpriteBatch batch, boolean shotgun, boolean angry, boolean flash, boolean windup,
                     float x, float feetY, float walkTime, boolean right, Color tint) {
        int frame = windup ? 5 : walkTime == 0 ? 4 : (int) (walkTime * 8f) % 4;
        int row = flash ? 2 : angry ? 1 : 0;
        float bob = windup ? 0f : MathUtils.sin(walkTime * 16f) * 0.008f;
        batch.setColor(flash ? Color.WHITE : tint);
        batch.draw(shotgun ? shell : bullet, x - 16f / PPU, feetY - 2f / PPU + bob,
                32f / PPU, 40f / PPU, frame * 32, row * 40, 32, 40, !right, false);
        batch.setColor(Color.WHITE);
    }

    public void weapon(SpriteBatch batch, boolean shotgun, float x, float y, float angle, float recoil) {
        float pull = recoil * 0.28f;
        x -= MathUtils.cosDeg(angle) * pull;
        y -= MathUtils.sinDeg(angle) * pull;
        boolean left = MathUtils.cosDeg(angle) < 0;
        float gripX = 8f / PPU;
        float gripY = (left ? 11f : 5f) / PPU;
        batch.setColor(Color.WHITE);
        batch.draw(weapons, x - gripX, y - gripY, gripX, gripY, 32f / PPU, 16f / PPU,
                1, 1, angle, shotgun ? 32 : 0, 0, 32, 16, false, left);
    }

    @Override
    public void dispose() {
        bullet.dispose();
        shell.dispose();
        weapons.dispose();
    }
}
